    let v1: Vec<i32> = Vec::from_slice(&[]);
    assert!(remove_duplicates(&v1) == 0);

    let v2 = Vec::from_slice(&[1, 1, 2, 3, 3, 3, 4]);
    assert!(remove_duplicates(&v2) == 4);

    let v3 = Vec::from_slice(&[-5, -5, -5, -5]);
    assert!(remove_duplicates(&v3) == 1);
